#[inline]
fn read_byte(buf: &[u8], idx: i32) -> u8 {
    if idx < 0 {
        return 0;
    }
    buf.get(idx as usize).copied().unwrap_or(0)
}

fn get_bits(buf: &[u8], pos: &mut i32, limit: i32, n: i32) -> u32 {
    let s = (*pos & 7) as u32;
    let shl0 = n + s as i32;
    let byte0 = *pos >> 3;
    *pos = pos.wrapping_add(n);
    if *pos > limit {
        return 0;
    }
    let mut next: u32 = (read_byte(buf, byte0) as u32) & (255u32 >> s);
    let mut cache: u32 = 0;
    let mut shl = shl0;
    let mut off = byte0.wrapping_add(1);
    loop {
        shl -= 8;
        if shl <= 0 {
            break;
        }
        cache |= next << (shl as u32);
        next = read_byte(buf, off) as u32;
        off = off.wrapping_add(1);
    }
    cache | (next >> ((-shl) as u32))
}

pub fn read_scalefactors(
    bs_buf: &[u8],
    bs_pos: &mut i32,
    bs_limit: i32,
    pba: &[u8],
    scfcod: &[u8],
    bands: i32,
    scf: &mut [f32],
) {
    let mut i: i32 = 0;
    let mut scf_idx: usize = 0;
    while i < bands {
        let mut s: f32 = 0.0;
        let ba_byte = pba.get(i as usize).copied().unwrap_or(0);
        let ba: i32 = ba_byte as i32;
        let scfcod_val = scfcod.get(i as usize).copied().unwrap_or(0);
        let mask: i32 = if ba != 0 {
            4 + (19i32.wrapping_shr(scfcod_val as u32) & 3)
        } else {
            0
        };
        let mut m: i32 = 4;
        while m != 0 {
            if (mask & m) != 0 {
                let b = get_bits(bs_buf, bs_pos, bs_limit, 6);
                let idx = ba.wrapping_mul(3).wrapping_sub(6).wrapping_add((b % 3) as i32);
                s = if idx >= 0 && (idx as usize) < G_DEQ_L12.len() {
                    G_DEQ_L12[idx as usize] * ((1i32 << 21).wrapping_shr(b / 3) as f32)
                } else {
                    0.0
                };
            }
            if let Some(slot) = scf.get_mut(scf_idx) {
                *slot = s;
            }
            scf_idx += 1;
            m >>= 1;
        }
        i = i.wrapping_add(1);
    }
}
