use crate::logic;

#[repr(C)]
pub struct BsT {
    pub buf: *const u8,
    pub pos: i32,
    pub limit: i32,
}

#[no_mangle]
pub unsafe extern "C" fn read_scalefactors(
    bs: *mut BsT,
    pba: *mut u8,
    scfcod: *mut u8,
    bands: i32,
    scf: *mut f32,
) {
    let bands_n: usize = if bands > 0 { bands as usize } else { 0 };

    let (bs_buf_ptr, mut pos, limit): (*const u8, i32, i32) = if bs.is_null() {
        (core::ptr::null(), 0, 0)
    } else {
        ((*bs).buf, (*bs).pos, (*bs).limit)
    };

    let byte_len: usize = if limit > 0 {
        ((limit as i64 + 7) / 8) as usize
    } else {
        0
    };

    let bs_buf: &[u8] = if bs_buf_ptr.is_null() || byte_len == 0 {
        &[]
    } else {
        core::slice::from_raw_parts(bs_buf_ptr, byte_len)
    };

    let pba_slice: &[u8] = if pba.is_null() || bands_n == 0 {
        &[]
    } else {
        core::slice::from_raw_parts(pba, bands_n)
    };

    let scfcod_slice: &[u8] = if scfcod.is_null() || bands_n == 0 {
        &[]
    } else {
        core::slice::from_raw_parts(scfcod, bands_n)
    };

    let scf_len: usize = bands_n.checked_mul(3).unwrap_or(0);
    let scf_slice: &mut [f32] = if scf.is_null() || scf_len == 0 {
        &mut []
    } else {
        core::slice::from_raw_parts_mut(scf, scf_len)
    };

    logic::read_scalefactors(
        bs_buf,
        &mut pos,
        limit,
        pba_slice,
        scfcod_slice,
        bands,
        scf_slice,
    );

    if !bs.is_null() {
        (*bs).pos = pos;
    }
}
